from rest_framework.decorators import api_view, permission_classes
from rest_framework.permissions import IsAuthenticated
from rest_framework.response import Response
from rest_framework import status
from webpush.models import PushInformation, Group

@api_view(['POST'])
@permission_classes([IsAuthenticated])
def update_subscription_group(request, subscription_id):
    group_name = request.data.get('group')
    # Validate that the subscription belongs to the authenticated user
    push_info = PushInformation.objects.filter(id=subscription_id, user=request.user).first()
    if not push_info:
        return Response({"error": "Subscription not found"}, status=status.HTTP_404_NOT_FOUND)

    group, _ = Group.objects.get_or_create(name=group_name)
    push_info.group = group
    push_info.save(update_fields=['group'])
    return Response({"status": "Group updated", "subscription_id": subscription_id, "group": group_name})
